FindingExplanation explainFinding(String id, String title, String advice, {required bool persian}) {
  final copy = _copy[id];
  if (copy == null) {
    return FindingExplanation(title,
      persian ? 'این یافته از یک قاعده سفارشی یا بررسی تخصصی به دست آمده است. شواهد و پیشنهاد اصلی را با توجه به کاربرد بررسی کنید.'
        : 'This observation comes from a custom or specialized rule. Review the evidence and original recommendation in context.',
      advice);
  }
  return FindingExplanation(persian ? copy[0] : title, persian ? copy[2] : copy[1], persian ? copy[3] : advice);
}
